      const articles = [
        {
          title: "The after-dark capsule wardrobe",
          type: "Style guide",
          body: "Five textures our editors are pairing for gallery nights, rooftop dinners, and late trains home.",
          link: "Read the guide",
          gradient: "linear-gradient(135deg, #2f2439, #6a441c 60%, #111522)",
