          body: "Moody serveware, candlelight, and small luxuries that make casual gatherings feel intentional.",
          link: "Shop the edit",
          gradient: "linear-gradient(135deg, #151b2a, #4a2f50)",
        },
      ];

      const escapeHtml = (value) =>
        String(value).replace(/[&<>"']/g, (character) => {
          const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#39;",
          };
          return entities[character];
        });

      const Header = () => `
        <header class="site-header">
          <div class="header-inner">
