            <div class="hero-badge">
              <strong>Drop 04</strong>
              <span>Metallic knits, satin shoes, and evening carryalls are now live.</span>
            </div>
          </div>
        </section>
      `;

      const ProductCard = (product) => `
        <article class="card product-card">
          <div
            class="product-media"
            style="--product-gradient: ${escapeHtml(product.gradient)}"
            aria-hidden="true"
          ></div>
          <div class="product-body">
            <div class="meta-row">
              <span>${escapeHtml(product.category)}</span>
              <span>${escapeHtml(product.tag)}</span>
            </div>
            <h3>${escapeHtml(product.name)}</h3>
            <div class="price-row">
              <span class="price">${escapeHtml(product.price)}</span>
              <button class="add-button" type="button" aria-label="Add to cart: ${escapeHtml(product.name)}">Add to cart</button>
            </div>
          </div>
        </article>
      `;

      const DealCard = (deal) => `
        <article class="card deal-card">
          <h3>${escapeHtml(deal.title)}</h3>
          <span class="deal-value">${escapeHtml(deal.value)}</span>
          <p>${escapeHtml(deal.body)}</p>
          <a href="#newsletter">Claim this deal</a>
        </article>
      `;

      const ArticleCard = (article) => `
        <article class="card article-card ${article.featured ? "featured" : ""}">
          <div
            class="article-media"
            style="--article-gradient: ${escapeHtml(article.gradient)}"
            aria-hidden="true"
          ></div>
          <p class="eyebrow">${escapeHtml(article.type)}</p>
          <h3>${escapeHtml(article.title)}</h3>
          <p>${escapeHtml(article.body)}</p>
          <a href="#featured">${escapeHtml(article.link)}</a>
        </article>
      `;

      const SectionHeading = ({ id, eyebrow, title, intro, link }) => `
        <div class="section-heading">
          <div>
            <p class="eyebrow">${escapeHtml(eyebrow)}</p>
            <h2 id="${escapeHtml(id)}">${escapeHtml(title)}</h2>
